export function resolveTechId(rawInput: string): string {
  if (!rawInput) return "";
  const clean = rawInput.toLowerCase().trim();
  const normalized = clean.replace(/[\s\.\-_/]/g, "");

  // 1. Direct match on catalog id (e.g. "nodejs", "nuxt", "gcp", "css3")
  const byId = TECH_CATALOG.find(
    (item) => item.id.toLowerCase() === clean || item.id.toLowerCase() === normalized
  );
  if (byId) return byId.id;

  // 2. Direct match on catalog display name (e.g. "Node.js", "Nuxt.js", "Vue.js", "Tailwind CSS")
  const byName = TECH_CATALOG.find(
    (item) => item.name.toLowerCase() === clean
  );
  if (byName) return byName.id;

  // 3. Direct match on normalized name (e.g. "nodejs" == "node.js", "tailwindcss" == "tailwind css")
  const byNormName = TECH_CATALOG.find(
    (item) => item.name.toLowerCase().replace(/[\s\.\-_/]/g, "") === normalized
  );
  if (byNormName) return byNormName.id;

  // 4. Exact match on keyword (e.g. "node", "nuxt", "vue", "ts", "js", "postgres", "psql")
  const byExactKw = TECH_CATALOG.find((item) =>
    item.keywords.some(
      (kw) =>
        kw.toLowerCase() === clean ||
        kw.toLowerCase().replace(/[\s\.\-_/]/g, "") === normalized
    )
  );
  if (byExactKw) return byExactKw.id;

  // 5. Explicit safe prefix / word mappings
  if (clean.startsWith("node")) return "nodejs";
  if (clean.startsWith("nuxt")) return "nuxt";
  if (clean.startsWith("next")) return "nextjs";
  if (clean.startsWith("vue")) return "vue";
  if (clean.startsWith("react native") || clean.includes("reactnative")) return "reactnative";
  if (clean.startsWith("react")) return "react";
  if (clean.startsWith("tailwind")) return "tailwind";
  if (clean.startsWith("nest")) return "nestjs";
  if (clean.startsWith("express")) return "express";
  if (clean.startsWith("postgre") || clean.startsWith("psql")) return "postgresql";
  if (clean.startsWith("mongo")) return "mongodb";
  if (clean.startsWith("my sql") || clean.startsWith("mysql")) return "mysql";
  if (clean.startsWith("flutter")) return "flutter";
  if (clean.startsWith("docker")) return "docker";
  if (clean.startsWith("k8s") || clean.startsWith("kubernetes")) return "kubernetes";
  if (clean.startsWith("type") || clean === "ts") return "typescript";
  if (clean.startsWith("java") && !clean.includes("script")) return "java";
  if (clean.includes("script") || clean === "js") return "javascript";
  if (clean.startsWith("css") || clean === "css3") return "css3";
  if (clean.startsWith("html")) return "html5";
  if (clean.startsWith("boot")) return "bootstrap";
  if (clean.startsWith("sass") || clean.startsWith("scss")) return "sass";
  if (clean.startsWith("graph")) return "graphql";
  if (clean.startsWith("py")) return "python";
  if (clean.startsWith("djang")) return "django";
  if (clean.startsWith("fastapi")) return "fastapi";
  if (clean.startsWith("php")) return "php";
  if (clean.startsWith("larav")) return "laravel";
  if (clean.startsWith("spring")) return "springboot";
  if (clean.startsWith("golang") || clean === "go") return "golang";
  if (clean.startsWith("dotnet") || clean.includes(".net") || clean.includes("c#")) return "dotnet";
  if (clean.startsWith("rest") || clean.includes("api")) return "restapi";
  if (clean.startsWith("swift") || clean === "ios") return "swift";
  if (clean.startsWith("kotl")) return "kotlin";
  if (clean.startsWith("android")) return "android";
  if (clean.startsWith("ionic")) return "ionic";
  if (clean.startsWith("redis")) return "redis";
  if (clean.startsWith("fireb")) return "firebase";
  if (clean.startsWith("supab")) return "supabase";
  if (clean.startsWith("aws") || clean.includes("amazon")) return "aws";
  if (clean.startsWith("gcp") || (clean.includes("google") && clean.includes("cloud"))) return "gcp";
  if (clean.startsWith("git")) return "git";
  if (clean.startsWith("nginx")) return "nginx";
  if (clean.startsWith("cloudf")) return "cloudflare";
  if (clean.includes("adwords") || (clean.includes("google") && clean.includes("ad"))) return "googleads";
  if (clean.includes("meta") || clean.includes("facebook")) return "metaads";
  if (clean.includes("analytic") || clean.includes("ga4")) return "analytics";
  if (clean.includes("search console") || clean.includes("searchconsole") || clean.includes("gsc")) return "searchconsole";
  if (clean.includes("tag manager") || clean.includes("tagmanager") || clean.includes("gtm")) return "tagmanager";
  if (clean.includes("seo")) return "seo";
  if (clean.includes("semrush")) return "semrush";
  if (clean.includes("ahref")) return "ahrefs";
  if (clean.includes("mailchimp")) return "mailchimp";
  if (clean.includes("hubspot")) return "hubspot";
  if (clean.includes("tiktok")) return "tiktokads";
  if (clean.includes("content") || clean.includes("copywrit")) return "contentmarketing";
  if (clean.includes("figma")) return "figma";
  if (clean.includes("photoshop") || clean === "ps") return "photoshop";
  if (clean.includes("blender")) return "blender";

  return clean;
}

export function renderTechSvg(rawId: string, className: string = "w-4 h-4") {
  const iconId = resolveTechId(rawId);
  const icon = TECH_ICON_PATHS[iconId];
  if (!icon) {
    return <Cpu className={className} />;
  }

  return (
    <svg
      className={className}
      viewBox={icon.viewBox || "0 0 24 24"}
      fill="currentColor"
    >
      <path d={icon.path} />
    </svg>
  );
}

export function getTechIcon(name: string, className: string = "w-4 h-4 text-[#0167D6]") {
  return renderTechSvg(name, className);
}
